begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select plan(11);
select set_config('test.fasted_day',nb.user_day_of(now(),'UTC')::text,true);
insert into auth.users(id) values ('07070707-0000-4000-8000-000000000001'),('07070707-0000-4000-8000-000000000002');
insert into public.profiles(user_id,timezone) values ('07070707-0000-4000-8000-000000000001','UTC') on conflict(user_id) do update set timezone='UTC';
insert into public.consents(user_id,consent_version,choice,text_sha256,locale) values ('07070707-0000-4000-8000-000000000001','test','granted','test','en');
insert into public.meals(id,user_id,user_day,slot,kcal,client_op_id) values ('07070707-0000-4000-8000-000000000003','07070707-0000-4000-8000-000000000001',current_setting('test.fasted_day')::date,'LUNCH',500,'07070707-0000-4000-8000-000000000004');
select set_config('request.jwt.claim.sub','07070707-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.mark_day_fasted(current_setting('test.fasted_day')::date)$$,'22023','FOOD_REQUIRES_CONFIRMATION','server also requires confirmation for existing meals');
select is(public.mark_day_fasted(current_setting('test.fasted_day')::date,true)->>'intake_state','FASTED','confirmed fasting receipt');
select is((select count(*)::integer from public.meals where deleted_at is null),0,'all meals cleared atomically');
select is(public.mark_day_fasted(current_setting('test.fasted_day')::date)->>'intake_state','FASTED','retry is idempotent');
select is((select count(*)::integer from public.fasted_days),1,'single durable fact');
select throws_ok($$select public.mark_day_fasted(current_setting('test.fasted_day')::date-1)$$,'22023','NOT_TODAY','past day cannot be cleared');
reset role;
select is((select intake_state from nb.compute_fuel('07070707-0000-4000-8000-000000000001',current_setting('test.fasted_day')::date)),'FASTED','recompute preserves fasting');
select is((select kcal_in from nb.compute_fuel('07070707-0000-4000-8000-000000000001',current_setting('test.fasted_day')::date)),0,'fasted is explicit zero');
select throws_ok($$insert into public.meals(user_id,user_day,slot,kcal,client_op_id) values ('07070707-0000-4000-8000-000000000001',current_setting('test.fasted_day')::date,'DINNER',200,'07070707-0000-4000-8000-000000000005')$$,'22023','DAY_ALREADY_FASTED','late meal cannot resurrect food');
select nb.recompute_range('07070707-0000-4000-8000-000000000001',current_setting('test.fasted_day')::date,current_setting('test.fasted_day')::date,'fasting_test');
select is((select protein_in_g::integer + carb_in_g::integer + fat_in_g::integer from public.day_fuel where user_id='07070707-0000-4000-8000-000000000001' limit 1),0,'settled fasting macros stay explicit zero');
select set_config('request.jwt.claim.sub','07070707-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*)::integer from public.fasted_days),0,'RLS isolates fasting facts');
select * from finish();
rollback;
